"""Evaluate Suricata rules generated by the hypothesis pipeline.

Generates attack/benign/variant pcaps, runs Suricata, computes TPR/FPR.

Usage (inside Docker):
    python scripts/eval_suricata_e2e.py \
        --pipeline-output output/hypothesis_v7 \
        --traces-dir benchmarks/traces \
        --ground-truth benchmarks/ground_truth.json \
        --output-dir output/suricata_eval
"""

import argparse
import json
import logging
import os
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent.parent))

from src.evaluation.pcap_generator import (
    generate_attack_pcap,
    generate_variant_pcaps,
    generate_benign_pcap,
    generate_common_benign_pcaps,
)
from src.evaluation.suricata_runner import run_suricata, validate_rules
from src.evaluation.metrics import (
    compute_per_cve_metrics,
    compute_aggregate_metrics,
    compute_class_metrics,
    format_results_table,
    save_evaluation_report,
)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(name)s] %(levelname)s: %(message)s",
)
logger = logging.getLogger("suricata_eval")


def load_ground_truth(gt_path: str) -> dict:
    with open(gt_path, encoding="utf-8") as f:
        return {item["cve_id"]: item for item in json.load(f)}


from src.hypothesis.rule_postprocess import (
    is_degenerate as _is_degenerate_canonical,
    reorder_sticky_buffers as _reorder_sticky_buffers,
)


def _is_degenerate(rule: str) -> bool:
    """Delegate to canonical is_degenerate() from rule_postprocess."""
    return _is_degenerate_canonical(rule) is not None


def collect_rules(pipeline_output_dir: str) -> dict:
    """Collect Suricata rules from pipeline output files.

    Returns dict of cve_id -> rule_text (degenerate rules excluded).
    """
    rules = {}
    degenerate_ids = []
    out_dir = Path(pipeline_output_dir)
    for result_file in sorted(out_dir.glob("CVE-*.json")):
        cve_id = result_file.stem
        try:
            with open(result_file, encoding="utf-8") as f:
                result = json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            logger.warning("Could not read %s: %s", result_file, e)
            continue

        if result.get("status") != "success":
            logger.info("Skipping %s (status=%s)", cve_id, result.get("status"))
            continue

        rule = result.get("suricata_rule", "")
        if rule and not rule.startswith("#"):
            if _is_degenerate(rule):
                degenerate_ids.append(cve_id)
                logger.info("Degenerate rule excluded: %s", cve_id)
                continue
            rules[cve_id] = rule
        else:
            logger.warning("No valid rule for %s", cve_id)

    if degenerate_ids:
        logger.info("Excluded %d degenerate rules: %s",
                    len(degenerate_ids), degenerate_ids)
    return rules


def _postprocess_rule(rule: str) -> str:
    """Apply rule normalization for evaluation.

    - Path traversal rules: use http.uri.raw instead of http.uri
      (Suricata normalizes ../ in http.uri, making PT rules miss)
    """
    import re
    if "../" in rule or r"\.\." in rule or "%2e%2e" in rule.lower():
        rule = rule.replace("http.uri;", "http.uri.raw;")
        rule = rule.replace("http_uri;", "http.uri.raw;")
        rule = re.sub(r'\bhttp\.uri\b(?!\.raw)', 'http.uri.raw', rule)
        if "pcre:" in rule and "http.uri.raw" not in rule.split("pcre:")[0]:
            before_pcre = rule.split("pcre:")[0]
            non_uri = any(b in before_pcre for b in
                          ("http.request_body;", "http_client_body;",
                           "file.data;", "http.cookie;", "http.header;",
                           "http.host;"))
            if not non_uri:
                rule = rule.replace("pcre:", "http.uri.raw; pcre:", 1)
    return rule


def write_combined_rules(rules: dict, output_path: str,
                         sid_start: int = 1000001) -> dict:
    """Write all rules to a single file, assigning unique SIDs.

    Returns dict of cve_id -> assigned SID.
    """
    import re
    Path(output_path).parent.mkdir(parents=True, exist_ok=True)
    sid_map = {}
    with open(output_path, "w", encoding="utf-8") as f:
        for i, (cve_id, rule) in enumerate(sorted(rules.items())):
            sid = sid_start + i
            sid_map[cve_id] = sid

            fixed = _reorder_sticky_buffers(rule)
            fixed = _postprocess_rule(fixed)

            # Replace existing sid or add one
            if re.search(r"sid:\s*\d+", fixed):
                fixed = re.sub(r"sid:\s*\d+", f"sid:{sid}", fixed)
            else:
                fixed = fixed.rstrip(")") + f" sid:{sid}; rev:1;)"

            # Add CVE reference in msg if not present
            if cve_id not in fixed:
                fixed = re.sub(
                    r'msg:\s*"([^"]*)"',
                    f'msg:"{cve_id} - \\1"',
                    fixed,
                )

            f.write(fixed.strip() + "\n")

    logger.info("Combined rules written to %s (%d rules)", output_path, len(sid_map))
    return sid_map


def load_trace_request(trace_path: str) -> dict:
    """Load HTTP request from a trace file."""
    with open(trace_path, encoding="utf-8") as f:
        trace = json.load(f)
    req = trace.get("trace", {}).get("request", {})
    return {
        "method": req.get("method", "GET"),
        "path": req.get("path", "/"),
        "params": req.get("params", {}),
        "headers": req.get("headers", {}),
        "body": req.get("body"),
    }


def mark_expected_sid(result: dict, expected_sid: int) -> dict:
    """Annotate a Suricata result with whether this CVE's assigned SID fired."""
    sids = set(result.get("rule_sids", set()))
    result["expected_sid"] = expected_sid
    result["expected_sid_triggered"] = expected_sid in sids
    return result


def main():
    parser = argparse.ArgumentParser(
        description="Evaluate Suricata rules from hypothesis pipeline")
    parser.add_argument("--pipeline-output", required=True,
                        help="Directory with pipeline output (CVE-*.json)")
    parser.add_argument("--traces-dir", default="benchmarks/traces",
                        help="Directory with trace JSON files")
    parser.add_argument("--ground-truth", default="benchmarks/ground_truth.json")
    parser.add_argument("--benign-traces-dir", default="benchmarks/traces_benign",
                        help="Directory with real benign traffic traces (UNSW-IoTraffic)")
    parser.add_argument("--benign-pattern", default="BENIGN-UNSW-*.json",
                        help="Glob for real benign traces (e.g. BENIGN-CSIC-*.json)")
    parser.add_argument("--output-dir", default="output/suricata_eval")
    parser.add_argument("--workers", type=int, default=8,
                        help="Parallel workers for Suricata evaluation")
    args = parser.parse_args()

    out_dir = Path(args.output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    gt = load_ground_truth(args.ground_truth)
    logger.info("Loaded %d ground truth entries", len(gt))

    # Step 1: Collect rules
    logger.info("Step 1: Collecting Suricata rules...")
    rules = collect_rules(args.pipeline_output)
    logger.info("Found %d valid rules", len(rules))

    if not rules:
        logger.error("No valid rules found. Run the hypothesis pipeline first.")
        sys.exit(1)

    rules_path = str(out_dir / "all_rules.rules")
    sid_map = write_combined_rules(rules, rules_path)

    # Step 1b: Validate rules, removing bad ones that would poison the whole file
    logger.info("Step 1b: Validating rules...")
    validation = validate_rules(rules_path,
                                str(out_dir / "rule_validation"))
    if not validation["valid"]:
        logger.warning("Rule validation failed — isolating bad rules")
        good_rules = {}
        for cve_id, rule_text in rules.items():
            import tempfile as _tf
            with _tf.NamedTemporaryFile(mode="w", suffix=".rules",
                                        delete=False) as tmp:
                fixed = _reorder_sticky_buffers(rule_text)
                fixed = _postprocess_rule(fixed)
                tmp.write(fixed + "\n")
                tmp_path = tmp.name
            v = validate_rules(tmp_path, str(out_dir / "rule_validation_tmp"))
            os.unlink(tmp_path)
            if v["valid"]:
                good_rules[cve_id] = rule_text
            else:
                logger.warning("Excluding invalid rule: %s", cve_id)
        if len(good_rules) < len(rules):
            logger.info("Kept %d/%d rules after validation", len(good_rules), len(rules))
            rules = good_rules
            sid_map = write_combined_rules(rules, rules_path)
    else:
        logger.info("All rules valid")

    # Step 2: Generate pcaps
    logger.info("Step 2: Generating pcap files...")
    pcap_dir = str(out_dir / "pcaps")
    traces_dir = Path(args.traces_dir)

    attack_pcaps = []
    benign_pcaps = []
    variant_pcaps = []

    for cve_id in sorted(rules.keys()):
        trace_file = traces_dir / f"{cve_id}.json"
        if not trace_file.exists():
            logger.warning("No trace file for %s", cve_id)
            continue

        http_req = load_trace_request(str(trace_file))

        # Attack pcap (original request)
        atk_path = str(Path(pcap_dir) / cve_id / "attack.pcap")
        generate_attack_pcap(http_req, atk_path)
        attack_pcaps.append((cve_id, atk_path))

        # Benign pcap (safe version — different endpoint for InfoLeak/AuthBypass)
        gt_entry = gt.get(cve_id, {})
        ben_path = str(Path(pcap_dir) / cve_id / "benign.pcap")
        generate_benign_pcap(http_req, ben_path,
                             vuln_class=gt_entry.get("vuln_class"))
        benign_pcaps.append((cve_id, ben_path))

        # Variant pcaps
        variants = generate_variant_pcaps(http_req, pcap_dir, cve_id)
        for v in variants:
            variant_pcaps.append((cve_id, v["type"], v["path"]))

    # Common benign traffic
    common = generate_common_benign_pcaps(pcap_dir)
    logger.info("Generated %d attack, %d benign, %d variant, %d common pcaps",
                len(attack_pcaps), len(benign_pcaps),
                len(variant_pcaps), len(common))

    # Step 3: Run Suricata (parallel)
    logger.info("Step 3: Running Suricata evaluation (%d workers)...", args.workers)
    suricata_log_dir = str(out_dir / "suricata_logs")
    start_time = time.time()

    # --- Attack ---
    def _eval_attack(item):
        cve_id, pcap_path = item
        log_dir = str(Path(suricata_log_dir) / cve_id / "attack")
        result = run_suricata(pcap_path, rules_path, log_dir)
        result = mark_expected_sid(result, sid_map[cve_id])
        return (cve_id, result)

    # --- Benign ---
    def _eval_benign(item):
        cve_id, pcap_path = item
        log_dir = str(Path(suricata_log_dir) / cve_id / "benign")
        result = run_suricata(pcap_path, rules_path, log_dir)
        result = mark_expected_sid(result, sid_map[cve_id])
        return (cve_id, result)

    # --- Variant ---
    def _eval_variant(item):
        cve_id, vtype, pcap_path = item
        log_dir = str(Path(suricata_log_dir) / cve_id / f"variant_{vtype}")
        result = run_suricata(pcap_path, rules_path, log_dir)
        result = mark_expected_sid(result, sid_map[cve_id])
        return (cve_id, vtype, result)

    # --- Common benign ---
    def _eval_common(item):
        log_dir = str(Path(suricata_log_dir) / "common_benign" /
                      Path(item["path"]).stem)
        result = run_suricata(item["path"], rules_path, log_dir)
        return (item, result)

    # --- Real benign ---
    def _eval_real_benign(trace_file_str):
        trace_file = Path(trace_file_str)
        trace_id = trace_file.stem
        try:
            http_req = load_trace_request(str(trace_file))
        except (json.JSONDecodeError, OSError, KeyError):
            return (trace_id, None, None)

        rb_pcap = str(Path(pcap_dir) / "real_benign" / f"{trace_id}.pcap")
        Path(rb_pcap).parent.mkdir(parents=True, exist_ok=True)
        generate_attack_pcap(http_req, rb_pcap)

        log_dir = str(Path(suricata_log_dir) / "real_benign" / trace_id)
        result = run_suricata(rb_pcap, rules_path, log_dir)
        return (trace_id, http_req, result)

    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        # Attack
        logger.info("  Evaluating %d attack pcaps...", len(attack_pcaps))
        attack_results = list(pool.map(_eval_attack, attack_pcaps))
        hits = sum(1 for _, r in attack_results if r["expected_sid_triggered"])
        logger.info("  Attack: %d/%d HIT", hits, len(attack_results))

        # Benign
        logger.info("  Evaluating %d benign pcaps...", len(benign_pcaps))
        benign_results = list(pool.map(_eval_benign, benign_pcaps))
        fps = sum(1 for _, r in benign_results if r["expected_sid_triggered"])
        logger.info("  Benign: %d/%d FP", fps, len(benign_results))

        # Variant
        logger.info("  Evaluating %d variant pcaps...", len(variant_pcaps))
        variant_results_list = list(pool.map(_eval_variant, variant_pcaps))

        # Common benign (synthetic)
        logger.info("  Evaluating %d common benign pcaps...", len(common))
        common_results = list(pool.map(_eval_common, common))

    common_fp = 0
    for item, result in common_results:
        if result["triggered"]:
            common_fp += 1
            logger.warning("  Common benign FP: %s", item["request"])

    # Real-world benign traffic (UNSW-IoTraffic)
    real_benign_dir = Path(args.benign_traces_dir)
    real_benign_fp = 0
    real_benign_total = 0
    real_benign_fp_sids = {}
    if real_benign_dir.exists():
        benign_trace_files = sorted(real_benign_dir.glob(args.benign_pattern))
        real_benign_total = len(benign_trace_files)
        logger.info("  Running %d real benign traces (UNSW-IoTraffic, %d workers)...",
                    real_benign_total, args.workers)

        with ThreadPoolExecutor(max_workers=args.workers) as pool:
            results = list(pool.map(_eval_real_benign,
                                    [str(f) for f in benign_trace_files]))

        for trace_id, http_req, result in results:
            if result is None:
                real_benign_total -= 1
                continue
            if result.get("triggered"):
                real_benign_fp += 1
                fired_sids = result.get("rule_sids", [])
                for sid in fired_sids:
                    real_benign_fp_sids.setdefault(sid, []).append(trace_id)
                logger.warning("  Real benign FP: %s (%s %s) SIDs=%s",
                               trace_id, http_req.get("method"),
                               http_req.get("path"), fired_sids)

        logger.info("  Real benign FPR: %d/%d (%.1f%%)",
                    real_benign_fp, real_benign_total,
                    100.0 * real_benign_fp / max(1, real_benign_total))
    else:
        logger.info("  No real benign traces dir found, skipping")

    elapsed = time.time() - start_time

    # Step 4: Compute metrics
    logger.info("Step 4: Computing metrics...")
    per_cve = compute_per_cve_metrics(
        attack_results, benign_results, variant_results_list)
    aggregate = compute_aggregate_metrics(per_cve)
    class_metrics = compute_class_metrics(per_cve, gt)

    aggregate["common_benign_fp"] = common_fp
    aggregate["common_benign_total"] = len(common)
    aggregate["real_benign_fp"] = real_benign_fp
    aggregate["real_benign_total"] = real_benign_total
    aggregate["real_benign_fpr"] = real_benign_fp / max(1, real_benign_total)
    aggregate["real_benign_fp_by_sid"] = {
        str(sid): len(traces) for sid, traces in real_benign_fp_sids.items()
    }
    aggregate["elapsed_seconds"] = elapsed

    # Print results
    print("\n" + "=" * 75)
    print("SURICATA RULE EVALUATION (RQ2)")
    print("=" * 75)
    print(f"\nRules evaluated: {aggregate['total']}")
    print(f"TPR (attack detection): {aggregate['tpr']:.1%} "
          f"({aggregate['true_positives']}/{aggregate['total']})")
    print(f"FPR (benign false alarm): {aggregate['fpr']:.1%} "
          f"({aggregate['false_positives']}/{aggregate['total']})")
    print(f"Common benign FP (synthetic): {common_fp}/{len(common)}")
    print(f"Real benign FP (UNSW-IoTraffic): {real_benign_fp}/{real_benign_total} "
          f"({100.0 * real_benign_fp / max(1, real_benign_total):.1f}%)")
    if real_benign_fp_sids:
        print(f"  Rules causing real FP: {len(real_benign_fp_sids)} distinct SIDs")
    print(f"Elapsed: {elapsed:.1f}s")

    if aggregate.get("variant_detection_rates"):
        print(f"\nVariant detection rates:")
        for vtype, rate in aggregate["variant_detection_rates"].items():
            print(f"  {vtype}: {rate:.1%}")

    print(f"\nPer-class metrics:")
    for cls, m in sorted(class_metrics.items()):
        print(f"  {cls:12s}: TPR={m['tpr']:.1%} FPR={m['fpr']:.1%} (n={m['total']})")

    print(f"\nPer-CVE results:")
    print(format_results_table(per_cve, gt))

    # Save report
    report_path = str(out_dir / "suricata_eval_report.json")
    save_evaluation_report(per_cve, aggregate, class_metrics, gt, report_path)
    print(f"\nFull report saved to {report_path}")


if __name__ == "__main__":
    main()
